-- GENERE par tools/resources/generate.py : NE PAS EDITER A LA MAIN. Rejouable (idempotent).
SET NAMES utf8mb4;
-- 008 : noeuds de ressources de PRODUCTION, cartes 0 et 1 (4664 noeuds ; plafond 6000). Genere par tools/resources/gen_nodes_production.py
-- Positions = positions de creatures de la table `creature` (jamais inventees) ; z et orientation = ceux de la creature.
-- Plage de guid 9510001-9599999. La validation 005 (9500001-9500999) n'est pas touchee. Le DELETE ne vise que des guid de la plage ET
-- des entrees de noeuds (9101001-9101999) : des pieces de construction posees ensuite (guid attribues apres le max) ne sont pas effacees.
-- Exclusions : points 010 (100 m), creatures a drapeaux PNJ (50 m), aires de villes/interieurs, eau (6 m), z hors terrain.
DELETE FROM `gameobject` WHERE `guid` BETWEEN 9510001 AND 9599999 AND `id` BETWEEN 9101001 AND 9101999;
